"""Verify the self-contained runtime archive and write a NEW reproduction plan.

No Java process is launched. All 129 distinct runtime artifacts and all packaged
files are checked. Classpath order is preserved in each 127-entry runtime. The
original scripts, absolute-path manifests and protocol remain unchanged. Two
separately identified script copies receive exact path-only substitutions, and
a derivative protocol points to newly written classpaths/manifests. Run the
printed command only after arranging a quiet, compatible Java 25.0.5+8 host.
"""

from __future__ import annotations

import argparse
import ast
import copy
import difflib
import json
import os
from pathlib import Path
import shlex
import shutil
import stat
import sys
import tempfile

from comparison_runtime_io import (BUNDLE_MANIFEST, FOLLOWUP, PROFILES, PROTOCOL, Inventory,
                                   file_hash, json_bytes, member_relative, path_under, publish_no_replace,
                                   require, sha_bytes, signature, verify_experiment, verify_profile_disclosure)


def replace_once(text: str, before: str, after: str, label: str) -> str:
    require(text.count(before) == 1, f"Expected exactly one reviewed path substitution: {label}")
    return text.replace(before, after)


def validate_bundle(repo: Path, expected_manifest_hash: str | None) -> tuple[Inventory, dict, dict, bytes]:
    path = path_under(repo, BUNDLE_MANIFEST)
    before = signature(path)
    require(stat.S_ISREG(before[2]), "Bundle manifest must be a regular file")
    data = path.read_bytes()
    require(signature(path) == before, "Bundle manifest changed while reading")
    require(expected_manifest_hash is None or sha_bytes(data) == expected_manifest_hash,
            "Bundle manifest differs from the externally supplied checksum")
    manifest = json.loads(data)
    require(manifest["format"] == 1 and manifest["archivePrefix"] == "rdf4j"
            and manifest["selfContainedRuntime"] is True and not manifest["jdkIncluded"]
            and not manifest["storesIncluded"] and manifest["protocolPath"] == PROTOCOL,
            "Unexpected comparison bundle format")
    inventory = Inventory(repo)
    names = set()
    for entry in manifest["files"]:
        relative = member_relative(entry["path"])
        require(relative not in names, f"Duplicate manifest file: {relative}")
        names.add(relative)
        observed = inventory.add(relative, entry["sha256"])
        require(observed == entry, f"Bundle file size/mode/identity differs: {relative}")
    require({entry["path"] for entry in manifest["profiles"]} == {"rdf4j/" + path for path in PROFILES},
            "Bundle must contain both sanitized diagnostic recordings")
    require(all(inventory.files[member_relative(entry["path"])] == entry for entry in manifest["profiles"]),
            "Sanitized JFR metadata differs from bundle inventory")
    require(verify_profile_disclosure(inventory) == manifest["recordingSanitizationReceipt"],
            "Recording sanitization receipt differs from the bundle manifest")
    experiment = verify_experiment(repo, inventory, manifest["originalRepository"])
    require(experiment["protocolSha256"] == manifest["protocolSha256"]
            and experiment["runtimes"] == manifest["runtimes"]
            and experiment["artifacts"] == manifest["runtimeArtifacts"]
            and len(experiment["artifacts"]) == 129,
            "Ordered runtime identity differs from bundle manifest")
    require(set(inventory.files) <= names, "Runtime verifier needed an unpackaged file")
    return inventory, manifest, experiment, data


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=Path(__file__).resolve().parents[2])
    parser.add_argument("--java", type=Path, required=True, help="Local compatible Java executable; not executed here")
    parser.add_argument("--output", type=Path, required=True, help="New directory outside the extracted rdf4j/ tree")
    parser.add_argument("--expected-manifest-sha256", help="Optional external checksum from runtime-verification.json")
    args = parser.parse_args()
    repo = args.repo.resolve(strict=True)
    output = args.output.parent.resolve(strict=True) / args.output.name
    require(not os.path.lexists(output) and not output.is_relative_to(repo),
            "The derivative plan must be new and outside the immutable extracted runtime")
    java = args.java.resolve(strict=True)
    require(java.is_file() and os.access(java, os.X_OK), "Java must be an executable regular file")
    require(os.pathsep not in str(repo) and "\n" not in str(repo), "Extraction path cannot be represented in a classpath")
    inventory, manifest, experiment, manifest_bytes = validate_bundle(repo, args.expected_manifest_sha256)
    manifest_signature = signature(path_under(repo, BUNDLE_MANIFEST))
    original_protocol = experiment["protocol"]
    derived = copy.deepcopy(original_protocol)
    derived["name"] = original_protocol["name"] + " — rebased reproduction"
    derived["java"] = str(java)
    products = {}
    rebased_manifests = {}
    descriptor_hash_fields = {"sourceManifestFile": "sourceManifestSha256", "provenanceFile": "provenanceSha256",
                              "productionPatchFile": "productionPatchSha256",
                              "originalSourceManifestFile": "originalSourceManifestSha256"}
    for name, runtime in experiment["runtimes"].items():
        entries = []
        for original, entry in zip(runtime["originalManifest"], runtime["entries"]):
            local = path_under(repo, member_relative(entry["path"]))
            require(os.pathsep not in str(local) and "\n" not in str(local), "Artifact path is not classpath-safe")
            entries.append(original | {"path": str(local)})
        rebased_manifests[name] = entries
        prefix = "runtimes/" + name + "/"
        classpath_bytes = (os.pathsep.join(entry["path"] for entry in entries) + "\n").encode("utf-8")
        manifest_data = json_bytes(entries)
        products[prefix + "classpath.txt"] = classpath_bytes
        products[prefix + "classpath-manifest.json"] = manifest_data
        descriptor = copy.deepcopy(runtime["descriptor"])
        descriptor.update({"classpathFile": str(output / prefix / "classpath.txt"),
                           "classpathFileSha256": sha_bytes(classpath_bytes),
                           "classpathManifestFile": str(output / prefix / "classpath-manifest.json"),
                           "classpathManifestSha256": sha_bytes(manifest_data)})
        for field, hash_field in descriptor_hash_fields.items():
            if field in runtime["descriptorPaths"]:
                relative = runtime["descriptorPaths"][field]
                descriptor[field] = str(path_under(repo, relative))
                require(inventory.files[relative]["sha256"] == descriptor[hash_field],
                        f"Relocated immutable descriptor hash differs: {name}/{field}")
        derived["runtimes"][name] = descriptor
        products[prefix + "runtime-descriptor.json"] = json_bytes(descriptor)
    products["base-classpath-manifest.json"] = json_bytes(rebased_manifests["original"][:126])
    driver_relative = FOLLOWUP + "/run-optimization-comparison.py"
    helper_relative = FOLLOWUP + "/runtime_identity.py"
    driver_before = inventory.read(driver_relative, original_protocol["driverSha256"]).decode("utf-8")
    helper_before = inventory.read(helper_relative, original_protocol["identityHelperSha256"]).decode("utf-8")
    driver_after = replace_once(driver_before,
                                "    if protocol['java'] != " + repr(original_protocol["java"]) + ":",
                                "    if protocol['java'] != " + repr(str(java)) + ":", "driver Java path guard")
    helper_after = replace_once(helper_before, "ROOT = Path(__file__).resolve().parents[2]",
                                "ROOT = Path(" + repr(str(repo)) + ")", "helper repository root")
    helper_after = replace_once(helper_after,
                                "ORIGINAL_CP = ROOT / 'result-coordinate-evidence/root-qualified-launcher/classpath.txt'",
                                "ORIGINAL_CP = Path(" + repr(str(output / "runtimes/original/classpath.txt")) + ")",
                                "helper original classpath")
    helper_after = replace_once(helper_after,
                                "ORIGINAL_MANIFEST = ROOT / 'result-coordinate-evidence/transport-comparison/classpath-manifest.json'",
                                "ORIGINAL_MANIFEST = Path(" + repr(str(output / "base-classpath-manifest.json")) + ")",
                                "helper original base manifest")
    ast.parse(driver_after)
    ast.parse(helper_after)
    products["run-optimization-comparison.py"] = driver_after.encode("utf-8")
    products["runtime_identity.py"] = helper_after.encode("utf-8")
    derived["driverSha256"] = sha_bytes(products["run-optimization-comparison.py"])
    derived["identityHelperSha256"] = sha_bytes(products["runtime_identity.py"])
    relocation = []
    for name, before, after in (("run-optimization-comparison.py", driver_before, driver_after),
                                ("runtime_identity.py", helper_before, helper_after)):
        relocation.extend(difflib.unified_diff(before.splitlines(keepends=True), after.splitlines(keepends=True),
                                              fromfile="a/" + name, tofile="b/" + name))
    products["path-relocation.patch"] = "".join(relocation).encode("utf-8")
    # JFR FileWrite paths are recorded data. The original analyzer compares them
    # with its current folder, so a separately identified copy must map that one
    # comparison to the original recorded prefix when extracted elsewhere.
    analyzer_before = inventory.read(FOLLOWUP + "/analyze-profiles.py").decode("utf-8")
    recorded_profile_prefix = manifest["originalRepository"] + "/" + FOLLOWUP + "/"
    analyzer_after = replace_once(
        analyzer_before, "e.get('path') == str(folder / 'samples.jsonl')",
        "e.get('path') == " + repr(recorded_profile_prefix) + " + folder.name + '/samples.jsonl'",
        "profile analyzer recorded samples path")
    ast.parse(analyzer_after)
    products["profile-reproduction/analyze-profiles.py"] = analyzer_after.encode("utf-8")
    products["profile-reproduction/analyzer-path-relocation.patch"] = "".join(difflib.unified_diff(
        analyzer_before.splitlines(keepends=True), analyzer_after.splitlines(keepends=True),
        fromfile="a/analyze-profiles.py", tofile="b/analyze-profiles.py")).encode("utf-8")
    extraction_commands = []
    for mode in ("off", "dense"):
        prefix = "profile-reproduction/frozen-" + mode + "/"
        source_prefix = FOLLOWUP + "/frozen-" + mode + "/"
        for filename in ("samples.jsonl", "arrival-trace.jsonl"):
            products[prefix + filename] = inventory.read(source_prefix + filename)
        products[prefix + "recorded-profile-analysis.json"] = inventory.read(source_prefix + "profile-analysis.json")
        extraction_commands.append({"argv": [str(java), str(path_under(repo, FOLLOWUP + "/ExtractJfr.java")),
                                               str(path_under(repo, FOLLOWUP + "/delivery-profiles/frozen-" + mode + "/profile.jfr")),
                                               str(output / prefix / "events.jsonl"),
                                               str(output / prefix / "event-counts.json")],
                                    "cwd": str(repo)})
    extraction_commands.append({"argv": [sys.executable, str(output / "profile-reproduction/analyze-profiles.py")],
                                "cwd": str(repo)})
    products["profile-reproduction/commands.json"] = json_bytes({
        "stepsInOrder": extraction_commands, "javaExecuted": False,
        "originalAnalyzerSha256": sha_bytes(analyzer_before.encode("utf-8")),
        "derivativeAnalyzerSha256": sha_bytes(analyzer_after.encode("utf-8")),
        "recordedDerivedExpansions": manifest["derivedExpansionsOmitted"],
        "inputScope": "Sanitized delivery copies; original raw recordings are not included.",
        "note": "Run separately from timing. Regenerate selected performance events from sanitized JFR and the exact extractor. Original expansion digests are provenance, not an assumed byte-equality target. The omitted failed first extraction is historical partial output, not a regeneration target."})
    derived["reproduction"] = {
        "originalProtocolSha256": experiment["protocolSha256"], "originalProtocolPath": PROTOCOL,
        "runtimeBundleManifestSha256": sha_bytes(manifest_bytes), "originalJava": original_protocol["java"],
        "originalDriverSha256": original_protocol["driverSha256"],
        "originalIdentityHelperSha256": original_protocol["identityHelperSha256"],
        "scriptChanges": "Four exact path-only substitutions: Java guard, repository root, original classpath and base manifest. No result/route/count/timing guard changes.",
        "note": "A separate reproduction with the exact frozen runtime bytes. It is not another observation in the original experiment.",
    }
    command = [sys.executable, str(output / "run-optimization-comparison.py"),
               "--protocol", str(output / "protocol.json"), "--output", str(output / "results")]
    products["protocol.json"] = json_bytes(derived)
    products["command.json"] = json_bytes({"argv": command, "cwd": str(repo)})
    products["verification.json"] = json_bytes({
        "format": 1, "validated": True, "javaExecuted": False, "originalInputsUnmodified": True,
        "bundleManifestSha256": sha_bytes(manifest_bytes), "protocolSha256": experiment["protocolSha256"],
        "reproductionProtocolSha256": sha_bytes(products["protocol.json"]),
        "validatedFiles": len(inventory.files), "uniqueRuntimeArtifacts": 129,
        "classpathEntries": {name: len(entries) for name, entries in rebased_manifests.items()},
        "replacedProductionIndex": 1, "sharedOtherEntries": 126,
        "pathRelocationPatchSha256": sha_bytes(products["path-relocation.patch"]),
        "originalDriverSha256": original_protocol["driverSha256"],
        "derivativeDriverSha256": derived["driverSha256"],
        "originalIdentityHelperSha256": original_protocol["identityHelperSha256"],
        "derivativeIdentityHelperSha256": derived["identityHelperSha256"],
        "profileAnalyzerPathOnlySubstitution": True,
        "originalProfileAnalyzerSha256": sha_bytes(analyzer_before.encode("utf-8")),
        "derivativeProfileAnalyzerSha256": sha_bytes(analyzer_after.encode("utf-8")),
    })
    products["README.md"] = (
        "# Rebased materializer reproduction plan\n\n"
        "All bundled files and ordered runtime identities were validated. The original inputs remain unchanged. "
        "The copies in this directory have only the four reviewed path substitutions in path-relocation.patch. "
        "The original fresh-JVM count, balanced order, eight warmups, five measurements, checksum, ledger, root-host "
        "and artifact guards are unchanged. Java has not run.\n\n"
        "Use Java 25.0.5+8 and arrange quiet serial execution. Run the argv recorded in command.json to produce "
        "a new results/ directory. A reproduction is separate evidence and must not be pooled with the recorded run.\n\n"
        "profile-reproduction/commands.json contains the ordered commands to regenerate both complete expanded event "
        "JSONLs and rerun the analyzer into new files. Its separately identified analyzer copy changes only the "
        "recorded FileWrite path comparison. Regeneration uses the sanitized delivery recordings; the private raw "
        "recordings, original analyzer and saved analysis remain unchanged.\n"
    ).encode("utf-8")
    products["SHA256SUMS"] = "".join(f"{sha_bytes(data)}  {name}\n" for name, data in sorted(products.items())).encode("ascii")
    staging = Path(tempfile.mkdtemp(prefix=".materializer-reproduction-", dir=output.parent))
    published = False
    try:
        for relative, data in products.items():
            path = staging / relative
            path.parent.mkdir(parents=True, exist_ok=True)
            with path.open("xb") as stream:
                stream.write(data)
        for relative, data in products.items():
            require(file_hash(staging / relative) == sha_bytes(data), f"Reproduction output readback differs: {relative}")
        inventory.assert_stable()
        require(signature(path_under(repo, BUNDLE_MANIFEST)) == manifest_signature,
                "Bundle manifest changed while preparing reproduction")
        publish_no_replace(staging, output)
        published = True
        print(f"Validated 129 distinct artifacts and all three 127-entry classpaths: {output}")
        print("No Java process has run. Explicit reproduction command (POSIX shell):")
        print(shlex.join(command))
    finally:
        if not published:
            shutil.rmtree(staging)


if __name__ == "__main__":
    try:
        main()
    except (OSError, ValueError, KeyError) as error:
        print(f"ERROR: {error}", file=sys.stderr)
        raise SystemExit(1)
